const CACHE_NAME="statsync-assets-v17",ASSETS_TO_CACHE=["./taskpane.html","./taskpane.js","./dialog.html","./dialog.js","https://appsforoffice.microsoft.com/lib/1.1/hosted/office.js"];self.addEventListener("install",e=>{self.skipWaiting(),e.waitUntil(caches.open(CACHE_NAME).then(e=>e.addAll(ASSETS_TO_CACHE)))}),self.addEventListener("activate",e=>{e.waitUntil(Promise.all([self.clients.claim(),caches.keys().then(e=>Promise.all(e.filter(e=>e!==CACHE_NAME).map(e=>caches.delete(e))))]))}),self.addEventListener("fetch",e=>{new URL(e.request.url);const t=e.request.url.startsWith(self.location.origin),s=e.request.url.includes("appsforoffice.microsoft.com");(t||s)&&e.respondWith(caches.match(e.request).then(t=>{const s=fetch(e.request).then(t=>{if(t&&(200===t.status||0===t.status)){const s=t.clone();caches.open(CACHE_NAME).then(t=>{t.put(e.request,s)})}return t}).catch(()=>new Response("Offline",{status:503,statusText:"Offline"}));return e.waitUntil(s),t||s}))});